import pytest

from app.errors import ValidationError
from app.features.discounts import apply_discount


def test_example():
    assert apply_discount("19.99", 10) == "$18.00"


def test_zero_percent_keeps_price():
    assert apply_discount("19.99", 0) == "$19.99"


def test_full_percent_is_free():
    assert apply_discount("19.99", 100) == "$0.00"


def test_discount_rounds_down():
    # 1999 * 33 // 100 = 659 discount cents -> 1340
    assert apply_discount("19.99", 33) == "$13.40"


def test_whole_dollar_and_single_decimal_inputs():
    assert apply_discount("20", 50) == "$10.00"
    assert apply_discount("$20.5", 10) == "$18.45"


@pytest.mark.parametrize("percent", [-1, 101, 1000])
def test_percent_out_of_range(percent):
    with pytest.raises(ValidationError):
        apply_discount("19.99", percent)


@pytest.mark.parametrize("percent", [10.5, "10", None, True])
def test_percent_not_int(percent):
    with pytest.raises(ValidationError):
        apply_discount("19.99", percent)


@pytest.mark.parametrize("price", ["", "abc", "-5.00", "1.234", "1,000", "$"])
def test_invalid_price(price):
    with pytest.raises(ValidationError):
        apply_discount(price, 10)

